#version 130
out vec4 FragColor;
uniform sampler2D SurfaceTex;
uniform sampler2D PaletteTex;
in vec4 TEX0;

void main()
{
    vec4 pIndex = texture(SurfaceTex, TEX0.xy);
    FragColor = texture(PaletteTex, vec2(pIndex.r * (255.0/256.0) + (0.5/256.0), 0));
}

#version 130
in vec4 VertexCoord;
in vec4 COLOR;
in vec4 TexCoord;
out vec4 COL0;
out vec4 TEX0;
uniform mat4 MVPMatrix;

void main()
{
    gl_Position = MVPMatrix * VertexCoord;
    COL0 = COLOR;
    TEX0.xy = TexCoord.xy;
}

