#version 110
uniform sampler2D SurfaceTex; 
uniform sampler2D PaletteTex; 
varying vec2 TEX0; 

void main()
{
   vec4 pIndex = texture2D(SurfaceTex, TEX0); 
   gl_FragColor = texture2D(PaletteTex, vec2(pIndex.r * (255.0/256.0) + (0.5/256.0), 0)); 
}

